+    if request_rate.is_finite() {
+        let e2els: Vec<f64> = successful.map(|o| o.latency + o.client_queue_time).collect();
+        metrics.e2el_including_client_queue = Some(latency_stats(&e2els, selected_percentiles));
+    }
+}
